"""Render the committed result files to `docs/benchmarks/index.md`, deterministically: sorted,
intervals not point estimates, limitations next to every study, no wall-clock time besides the
`started_at` of the data."""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

from .common import REPO, RESULTS_DIR, StudyResult, load_results

OUT = REPO / "docs" / "benchmarks" / "index.md"


def _fmt(v: float) -> str:
    return f"{v:.4g}"


def render(results: list[StudyResult]) -> str:
    lines = [
        "# Benchmarks",
        "",
        "Generated by `uv run python -m studies.render` from `benchmarks/results/*.json`. "
        "Negative results are kept; intervals are 95 percent; nothing is rounded up.",
        "",
    ]
    if not results:
        lines += ["No study results have been published yet.", ""]
    for r in sorted(results, key=lambda x: x.name):
        lines += [f"## {r.name}", ""]
        lines.append(
            f"Platform {r.platform_version}, seed {r.seed}, n = {r.n}, "
            f"run {r.started_at.isoformat()}" + (" (smoke configuration)" if r.smoke else "")
        )
        lines.append("")
        if r.metrics:
            lines += ["| Metric | Value | 95% interval |", "|---|---|---|"]
            for k in sorted(r.metrics):
                iv = r.intervals.get(k)
                cell = f"{_fmt(iv[0])} to {_fmt(iv[1])}" if iv else "n/a"
                lines.append(f"| {k} | {_fmt(r.metrics[k])} | {cell} |")
            lines.append("")
        lines += ["Limitations:", "", *[f"- {x}" for x in r.limitations]]
        if r.notes:
            lines += ["", f"Notes: {r.notes}"]
        lines.append("")
    return "\n".join(lines).rstrip() + "\n"


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(prog="studies.render")
    ap.add_argument("--results", type=Path, default=RESULTS_DIR)
    ap.add_argument("--out", type=Path, default=OUT)
    ns = ap.parse_args(argv)
    ns.out.parent.mkdir(parents=True, exist_ok=True)
    ns.out.write_text(render(load_results(ns.results)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
